mapper.select:
SELECT SDT.CARD_NO, SDT.DEVICE_CODE, SDT.SERVICE_TYPE, SDT.PARK_ID, SDT.TASK_TYPE, SDT.GENERAL, PERSON.PERSON_NAME, SDT.CREATE_TIME, PERSON.BADGE, SDT.START_TIME, SD.DEVICE_NAME, SD.DEVICE_TYPE, SDT.REMARK, SA.AREA_NAME FROM SMT_TASK_DOWN_RECORD SDT LEFT JOIN ( SELECT SLA. ID AS VEHICLE_ID, SLA.DRIVER_NAME AS PERSON_NAME, NULL AS BADGE FROM SMT_LOGISTICS_APPOINTMENT SLA UNION ALL SELECT SV. ID AS VEHICLE_ID, SV.VISITOR_NAME AS PERSON_NAME, NULL AS BADGE FROM SMT_VISITOR SV UNION ALL SELECT SNS.VEHICLE_ID AS VEHICLE_ID, SNS."NAME" AS PERSON_NAME, NULL AS BADGE FROM SMT_NOT_STAFF SNS UNION ALL SELECT SVS.VEHICLE_ID AS VEHICLE_ID, SS."NAME" AS PERSON_NAME, SS.BADGE AS BADGE FROM SMT_VEHICLE_STAFF SVS LEFT JOIN SMT_STAFF SS ON SVS.STAFF_ID = SS."ID" ) PERSON ON PERSON.VEHICLE_ID = SDT.CARD_NO LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SD.ID LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID
SDT.DEVICE_TYPE = 2
AND SDT.TASK_TYPE = #{query.taskType}
AND SDT.ACTION = #{query.action}
AND SDT.DEVICE_CODE = #{query.deviceCode}
AND PERSON.PERSON_NAME LIKE CONCAT(CONCAT('%',#{query.personName}),'%')
AND SDT.GENERAL LIKE CONCAT(CONCAT('%',#{query.general}),'%')
AND PERSON.BADGE = #{query.badge}
AND SD.DEVICE_TYPE = #{query.deviceType}
AND SA.ID = #{query.areaId}
AND SDT.TASK_TYPE = #{query.taskType}
AND SDT.SERVICE_TYPE = #{query.serviceType}
AND SDT.DEVICE_CODE = #{query.deviceCode}
AND SDT.START_TIME >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND SDT.START_TIME < TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd') + 1
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC

SELECT SDT.ID, SDT.CARD_NO, SDT.DEVICE_CODE, SDT.SERVICE_TYPE, SDT.PARK_ID, SDT.TASK_TYPE, SDT.GENERAL, SDT.CREATE_TIME, SS.BADGE, SDT.OVER_TIME, SDT.TASK_ID, SDT.START_TIME, SD.DEVICE_NAME, SD.DEVICE_TYPE, SDT.REMARK, SA.AREA_NAME FROM SMT_ISC_DOWN_RECORD SDT LEFT JOIN SMT_STAFF SS ON SDT.CARD_NO = SS."ID" LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SD.ID LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID
SDT.DEVICE_TYPE = 1
AND SDT.TASK_TYPE = #{query.taskType}
AND SDT.ACTION = #{query.action}
AND SDT.DEVICE_CODE = #{query.deviceCode}
AND SDT.GENERAL LIKE CONCAT(CONCAT('%',#{query.general}),'%')
AND SS.BADGE = #{query.badge}
AND SD.DEVICE_TYPE = #{query.deviceType}
AND SA.ID = #{query.areaId}
AND SDT.TASK_TYPE = #{query.taskType}
AND SDT.SERVICE_TYPE = #{query.serviceType}
AND SDT.DEVICE_CODE = #{query.deviceCode}
AND SDT.START_TIME >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND SDT.START_TIME < TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd') + 1
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC

SELECT SP. ID AS VALUE, SP.PARK_NAME AS LABEL FROM SMT_PARK SP
AND SP.ID IN
#{tempId}

SELECT SD. ID AS VALUE, SD.DEVICE_NAME AS LABEL FROM SMT_DEVICE SD
AND SD.PARK_ID = #{parkId}
AND SD.DEVICE_TYPE = #{type}
